pub fn bitwise_and(x1: &Vec<u8>, x2: &Vec<u8>) -> Vec<u8> {
    // Assumption per problem statement: x1.len() == x2.len()
    let mut out = Vec::with_capacity(x1.len());
    for i in 0..x1.len() {
        let a = x1[i];
        let b = x2[i];
        let r = a & b;

        // Property checks for every valid index (debug-only).
        debug_assert_eq!(r, a & b);     // produced element equals bitwise AND
        debug_assert_eq!(a & b, b & a); // commutativity on those elements
        debug_assert_eq!(a & 0u8, 0u8); // AND with zero yields zero
        debug_assert_eq!(a & a, a);     // idempotence
        debug_assert!(r <= a);          // result <= each operand
        debug_assert!(r <= b);

        out.push(r);
    }
    out
}

